function Make-Bridge([string]$Operation){
 $encode=$Operation -in @('BC','BW','BT');$write=$Operation -in @('BW','CW','BT','CT');$try=$Operation -in @('BT','CT');$sourceElement=if($encode){[char]}else{[byte]};$targetElement=if($encode){[byte]}else{[char]};$srcArray=$sourceElement.MakeArrayType();$dstArray=$targetElement.MakeArrayType();$roDef=[type]'System.ReadOnlySpan`1';$spanDef=[type]'System.Span`1';$ro=$roDef.MakeGenericType([type[]]@($sourceElement));$span=$spanDef.MakeGenericType([type[]]@($targetElement));[type[]]$signature=@([Text.Encoding],$srcArray,[int],[int]);[type[]]$native=@($ro)
