function Snapshot($values){if($null -eq $values){return $null};return ,([int[]]@($values|ForEach-Object{[int]$_}))}
$bridges=@{};foreach($op in @('BC','CC','GS','BW','CW','BT','CT')){$bridges[$op]=Make-Bridge $op};$rows=[Collections.Generic.List[object]]::new()
